"""
Light subtitle cue cleanup (WhisperJAV regexp_v09 subset + JA AV heuristics).

Removes common Japanese AV ASR artifacts: bracketed SFX/SDH markers,
music-note glyphs, Latin gibberish leaks, empty cues after strip.
Medium soft-scene moans are kept (compressed); only extreme NVV spam is dropped.
Wet/suck/lick oral SFX (ちゅっ/ごくっ/じゅる…）are stripped; lexical kiss verbs kept.

Phrase-level YouTube / filler hallucinations are handled in
``quality.is_hallucinated_cue`` / ``filter_hallucinated_cues`` (called from jobs).
"""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

# Targeted SFX / SDH markers in (), [], （）, 【】
_SFX_BRACKET = re.compile(
    r"[\(\[（【][^\)\]）】]*"
    r"(拍手|笑い?|音楽|泣き?|鳴き?|歓声|喘息|呼吸|ノイズ|SE|BGM|SFX|"
    r"息|喘ぎ|喘|息遣い|吐息|ため息|悶え|嬌声|水音|キス|接吻)"
    r"[^\)\]）】]*[\)\]）】]\s*",
)

# Short parentheticals (almost always SFX / stage directions in AV softsubs)
_SHORT_PAREN = re.compile(r"[\(（][^\)）]{1,40}[\)）]\s*")

# Tortoise-shell SDH 〔…〕
_TORTOISE = re.compile(r"〔[^〕]*〕\s*")

# Bare music-bracket / whole-cue SFX tokens
_MUSIC_TOKEN = re.compile(r"\[音楽\]|【音楽】|♪+|♫+|♩+|♬+")
_WHOLE_SFX = re.compile(
    r"^[\s\[\(（【〈《「『]*"
    r"(音楽|BGM|SE|SFX|ノイズ|息|吐息|ため息|喘息|喘ぎ|呼吸|笑い声|拍手|"
    r"水音|キス|接吻|沈黙|無音|"
    r"music|noise|applause|laughter|breathing|silence|moan(?:ing)?s?)"
    r"[\s\]\)）】〉》」』]*$",
    re.IGNORECASE,
)

# Elongated vowel / moan runs (ああああ / うーーー / んんんん)
_ELONGATED_RUN = re.compile(
    r"([あぁアァいぃイィうぅウゥえぇエェおぉオォんンー〜～っッ])\1{3,}"
)
# Whole-cue pure stutter commas: あ、あ、あ、あ
_STUTTER_COMMA_ONLY = re.compile(
    r"^([あぁアァうぅウゥんンー〜～っッ]{1,2}[、,]){3,}([あぁアァうぅウゥんンー〜～っッ]{1,2})?[、,]?$"
)
# Phrase stutter with commas ending the cue: ダメ、ダメ、ダメ、ダメ → ダメ…
_PHRASE_COMMA_STUTTER = re.compile(
    r"([ぁ-んァ-ン一-龥々ー]{1,8})([、,])(?:\1\2){2,}(?:\1)?(?=[、,。．.!！?？…\s]*$)"
)
# Leading short stutter before a longer continuation: こ、こ、こ、これ → こ、これ
_LEADING_KANA_STUTTER = re.compile(
    r"([ぁ-んァ-ンー]{1,2})([、,])(?:\1\2){2,}(?=[ぁ-んァ-ン一-龥々])"
)

# Cue is only non-lexical vocalization (NVV) — drop as subtitle noise
_NVV_ONLY = re.compile(
    r"^[あぁアァいぃイィうぅウゥえぇエェおぉオォんンー〜～っッっ"
    r"・･\.。…、,！!？?\s♡♥❤]+$"
)

# Wet / suck / lick oral SFX (ADN-791 etc.) — strip; keep moans (はぁ/あっ/んっ).
# Avoid lexical kiss verbs like ちゅうして / チューして / キスして.
_WET_ORAL_SFX_ATOM = (
    r"(?:"
    r"ん?ちゅっ|ん?ちゅぱっ?|ん?ちゅぽっ?|ん?ちゅぅ+|ん?ちゅる+[っッ]*"
    r"|ん?(?:ぢゅ|ヂュ)ぅ+"
    r"|ちゅうう+|ん?チュッ|ん?チュパッ?|ん?チュゥ+"
    r"|ちゅ(?=[…·.…!！?？、,\s]|$)"
    r"|チュー(?!して)[ーぅう]*"
    r"|ん?(?:ぢゅ|ヂュ|じゅ|ジュ)(?:っ|ぼっ?|ぽっ?|ぷっ?|る+[っッ]*|ぅ+)+"
    r"|ず(?:ぢゅ|じゅ)(?:ぼ|ぢゅぼ|じゅぼ)*[っッ]?"
    r"|くちゅ[うっんン]+|ぐちゅ[うっんン]+|クチュ+"
    r"|ごく[んっンッ]+|ゴク[リッんン]+|ごっくん|ゴックン"
    r"|コクン|こくん"
    r"|ぺろっ?|れろっ?|ペロ+|レロ+"
    r"|んぐっ?|ぷっ|あむっ|んむっ|んむぎゅ"
    r"|んにゅごっきゅ"
    r"|ぶっつぅ+|ぶっちゅう*"
    r"|ぬぷっ?|ぬちゅっ?"
    r")"
)
# Non-oral AV SFX whole cues (stomach growl / lotion drip / stage direction)
_AV_MISC_SFX_ONLY = re.compile(
    r"^[\s…·.•\-—_~～。．.!！?？、,，\[\]\(\)（）【】「」『』]*"
    r"(?:"
    r"[グぐ][ルる]+[っッ]*"
    r"|ブフッ?"
    r"|ロー+"
    r"|トゥゥ*"
    r"|チラッ"
    r"|ぱっ"
    r")"
    r"[\s…·.•\-—_~～。．.!！?？、,，]*$"
)
_WET_ORAL_SFX_TOKEN = re.compile(_WET_ORAL_SFX_ATOM)
_WET_ORAL_SFX_CHUNK = re.compile(
    rf"(?:{_WET_ORAL_SFX_ATOM}[\s、,．.…!！?？ー〜～・･]*)+"
)
_WET_ORAL_SFX_ONLY = re.compile(
    rf"^[\s…·.•\-—_~～。．.!！?？、,，\[\]\(\)（）【】「」『』]*"
    rf"(?:{_WET_ORAL_SFX_ATOM}[\s、,．.…!！?？ー〜～・･]*)+"
    rf"[\s…·.•\-—_~～。．.!！?？、,，]*$"
)

# Latin gibberish leaked into JA soft scenes (FNS-235: mainlyエヴェヴェ…)
_LATIN_GIBBER = re.compile(r"[A-Za-z]{4,}")
_KANA_GARBLED = re.compile(r"(ェ|ェェ|ヴェ|ヴ|mainly|subscribe|watching)", re.IGNORECASE)
# Latin jammed against CJK with no space (HMN-878: iz磨吉平洋 / 辉奈Det咲佑 / 鲁ved因)
_LATIN_CJK_JAM = re.compile(
    r"[A-Za-z]{2,}[\u3040-\u30ff\u4e00-\u9fff]|[\u3040-\u30ff\u4e00-\u9fff][A-Za-z]{2,}"
)

# Collapse leftover whitespace
_WS = re.compile(r"[ \t\u3000]+")
_SYMBOL_ONLY = re.compile(
    r"^[♪♫♩♬·.•…\-—_~～。．.!！?？、,，\s◆◇■□★☆●○◎※]+$"
)

