# Whisper hotword / term-list echoes (HMN-878 / JUR-809 / HMN-869)
_HOTWORD_ECHO_RE = re.compile(
    r"^(?:"
    r"お客様[：:].{0,40}(?:メンズエステ|マイクロビキニ|メンエス)"
    r"|お客様[：:](?:舞|トミー|さつき|サツキ|皐月|マイ)[。．.\s]*"
    r"|(?:オイルマッサージ){2,}"
    r"|オイルマ$"
    r"|(?:メンズエステ[、,．.\s]*){2,}"
    r"|[リり]*ギリギリ+の塩梅.*"
    r"|ギリギリの塩梅"
    r"|ストーリーマイクロビキニ"
    r")[、,．.\s]*$"
)
_TERM_LOOP_RE = re.compile(r"(オイルマッサージ|メンズエステ|マイクロビキニ)\1+")
_PURE_HAN_REPEAT_JUNK = re.compile(
    r"^[\u4e00-\u9fff]{2,8}$"
)
# Chinese filler loops leaked into JA ASR (好来好来 / 鼓励鼓励 / 冷冷冷 / 余余余)
_ZH_FILLER_LOOP = re.compile(r"([\u4e00-\u9fff]{1,3})\1{2,}")
_SUBTITLE_CREDIT_RE = re.compile(r"^字幕|李宗盛")


