def _decode_tdp_d01(path: Path):
    """Decode opaque DF01 domain-fix payload written by the desktop TDP runtime."""
    try:
        import zlib

        raw = path.read_bytes()
        if len(raw) < 5 or raw[:4] != b"DF01":
            return None
        key = b"TransubTdpDomain1"
        body = raw[4:]
        xored = bytes(b ^ key[i % len(key)] for i, b in enumerate(body))
        payload = json.loads(zlib.decompress(xored).decode("utf-8"))
        pairs = payload.get("pairs") if isinstance(payload, dict) else None
        if not isinstance(pairs, list):
            return None
        out = []
        for row in pairs:
            frm = str((row or {}).get("from") or "")
            to = str((row or {}).get("to") or "")
            if frm and to:
                out.append((frm, to))
        return out or None
    except Exception:
        return None


def _compile_ja_asr_domain_pairs(pairs):
    return tuple((re.compile(re.escape(frm)), to) for frm, to in pairs)


def _load_ja_asr_domain_fixes() -> tuple[tuple[re.Pattern[str], str], ...]:
    """Load TDP D01 overlay, else shared/ja-asr-domain-fixes.json when available."""
    import os

    candidates_df1 = []
    candidates_json = [
        Path(__file__).resolve().parents[4] / "shared" / "ja-asr-domain-fixes.json",
        Path(__file__).resolve().parents[5] / "shared" / "ja-asr-domain-fixes.json",
    ]

    tdp_dir = os.environ.get("TRANSUB_TDP_DIR")
    if tdp_dir:
        candidates_df1.insert(0, Path(tdp_dir) / "active" / "d01.df1")
    home = os.environ.get("TRANSUB_ENGINE_HOME") or os.environ.get("TRANSUB_APP_ROOT")
    if home:
        home_path = Path(home)
        candidates_json.insert(0, home_path / "shared" / "ja-asr-domain-fixes.json")
        candidates_json.insert(0, home_path.parent / "shared" / "ja-asr-domain-fixes.json")
        candidates_df1.append(home_path / "tdp" / "active" / "d01.df1")
        candidates_df1.append(home_path.parent / "tdp" / "active" / "d01.df1")

    for path in candidates_df1:
        try:
            if not path.is_file():
                continue
            pairs = _decode_tdp_d01(path)
            if pairs:
                return _compile_ja_asr_domain_pairs(pairs)
        except Exception:
            continue

    for path in candidates_json:
        try:
            if not path.is_file():
                continue
            data = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(data, list) or not data:
                continue
            pairs = []
            for row in data:
                frm = str((row or {}).get("from") or "")
                to = str((row or {}).get("to") or "")
                if frm and to:
                    pairs.append((frm, to))
            if pairs:
                return _compile_ja_asr_domain_pairs(pairs)
        except Exception:
            continue

    return _fallback_ja_asr_domain_fixes()


# Mens-esthe / soft-AV ASR mishears (Whisper: メンエス→免税, オイル→本島/アイル…)
_JA_ASR_DOMAIN_FIXES: tuple[tuple[re.Pattern[str], str], ...] = _load_ja_asr_domain_fixes()
_JA_ASR_DOMAIN_FIXES_MTIME = None
_JA_ASR_DOMAIN_FIXES_PATH = None


def _tdp_d01_watch_path():
    import os

    tdp_dir = os.environ.get("TRANSUB_TDP_DIR")
    if tdp_dir:
        return Path(tdp_dir) / "active" / "d01.df1"
    home = os.environ.get("TRANSUB_ENGINE_HOME") or os.environ.get("TRANSUB_APP_ROOT")
    if home:
        p = Path(home).parent / "tdp" / "active" / "d01.df1"
        if p.is_file():
            return p
        p2 = Path(home) / "tdp" / "active" / "d01.df1"
        if p2.is_file():
            return p2
    return None


def _maybe_reload_ja_asr_domain_fixes() -> None:
    """Hot-reload D01 when the active overlay file changes (Pro TDP updates)."""
    global _JA_ASR_DOMAIN_FIXES, _JA_ASR_DOMAIN_FIXES_MTIME, _JA_ASR_DOMAIN_FIXES_PATH
    path = _tdp_d01_watch_path()
    if path is None or not path.is_file():
        return
    try:
        mtime = path.stat().st_mtime
    except Exception:
        return
    key = str(path)
    if _JA_ASR_DOMAIN_FIXES_PATH == key and _JA_ASR_DOMAIN_FIXES_MTIME == mtime:
        return
    pairs = _decode_tdp_d01(path)
    if not pairs:
        return
    _JA_ASR_DOMAIN_FIXES = _compile_ja_asr_domain_pairs(pairs)
    _JA_ASR_DOMAIN_FIXES_MTIME = mtime
    _JA_ASR_DOMAIN_FIXES_PATH = key


def _apply_ja_asr_domain_fixes(text: str) -> str:
    _maybe_reload_ja_asr_domain_fixes()
    s = str(text or "")
    if not s:
        return s
    for pat, repl in _JA_ASR_DOMAIN_FIXES:
        s = pat.sub(repl, s)
    return s


_ESTHE_HINT_RE = re.compile(
    r"メンズエステ|メンエス|massage|esthe|オイルマッサージ|mens[-_]?esthe",
    re.IGNORECASE,
)
# School / sibling soft-AV — mens-esthe hotwords pollute ASR (IPZZ-745).
_NON_ESTHE_AV_HINT_RE = re.compile(
    r"学校|妹|兄|お兄|学園|制服|skirt|sister|brother|"
    # Studio codes that are rarely mens-esthe (Attackers ADN, etc.)
    r"\bipzz\b|\bsone\b|\bssis\b|\bsnis\b|\bmide\b|"
    r"\badn\b|\batid\b|\brbd\b|\bshkd\b|\bsame\b|\bfns\b|\bcjod\b|\bhmn\b",
    re.IGNORECASE,
)


def ja_av_domain_whisper_bias(*, hint: str = "") -> tuple[str, str]:
    """
    Compact Whisper bias for soft-AV JA (av_soft only).

    Mens-esthe vocabulary helps HMN/JUR massage titles, but on school/sibling
    titles (IPZZ-745) it steers the decoder toward unrelated esthe terms.
    Prefer short hotwords — Whisper echoes long prompts into cues.
    """
    sample = str(hint or "")
    esthe = bool(_ESTHE_HINT_RE.search(sample))
    non_esthe = bool(_NON_ESTHE_AV_HINT_RE.search(sample))
    if non_esthe and not esthe:
        prompt = "日本語の自然な会話。"
        hotwords = "お兄ちゃん 気持ちいい だめ エッチ あぁん"
        return prompt, hotwords
    prompt = "メンズエステの店内会話。"
    hotwords = (
        "メンズエステ メンエス オイル 指圧 半パンツ リンパ "
        "ふくらはぎ ほぐして うつ伏せ 仰向け ゲスト"
    )
    return prompt, hotwords


def _compress_elongated(text: str) -> str:
    """Collapse 4+ repeated moan/vowel glyphs to two + ellipsis for readability."""

    def _repl(m: re.Match[str]) -> str:
        ch = m.group(1)
        return f"{ch}{ch}…"

    return _ELONGATED_RUN.sub(_repl, text)


def _compress_stutter_phrases(text: str) -> str:
    """
    Compress JA AV stutter / stacked phrases inside one cue.

    Examples:
      ダメ、ダメ、ダメ、ダメ → ダメ…
      ダメダメダメダメ → ダメ…
      こ、こ、こ、これいちごめん → こ、これいちごめん
      あ、あ、あ、だめ → あ、だめ
    """
    s = str(text or "")
    if not s:
        return s
    # Same phrase repeated with commas (3+) — before leading-kana pass
    s = _PHRASE_COMMA_STUTTER.sub(r"\1…", s)
    # Leading kana stutter before a *different* continuation word
    s = _LEADING_KANA_STUTTER.sub(r"\1、", s)
    # Concatenated phrase ×3+: whole-cue, or cleanly before a non-prefix continuation
    m_full = re.fullmatch(
        r"([ぁ-んァ-ン一-龥々ー]{2,6})\1{2,}([、,。．.!！?？…\s]*)$",
        s,
    )
    if m_full and len(m_full.group(0)) - len(m_full.group(2) or "") >= 6:
        s = m_full.group(1) + "…" + (m_full.group(2) or "")
    else:
        m_head = re.match(r"(([ぁ-んァ-ン一-龥々ー]{2,6})\2{2,})(.+)$", s)
        if m_head and len(m_head.group(1)) >= 6:
            phrase = m_head.group(2)
            rest = m_head.group(3)
            orphan_prefix = any(
                rest.startswith(phrase[:i]) and not rest.startswith(phrase)
                for i in range(1, len(phrase))
            )
            if not orphan_prefix:
                s = phrase + "…" + rest
    # Tidy doubled ellipsis / trailing comma before ellipsis
    s = re.sub(r"…{2,}", "…", s)
    s = re.sub(r"[、,]…", "…", s)
    s = re.sub(r"…[、,]+", "…", s)
    return s.strip()


def _is_nvv_only(text: str) -> bool:
    """True when the cue is only extreme moan spam (no lexical JA).

    Medium soft-scene moans (あっ…んっ…) are kept and compressed; only drop
    stuck-decoder runs that drown the timeline.
    """
    raw = str(text or "").strip()
    if not raw:
        return True
    if not _NVV_ONLY.match(raw):
        return False
    bare = re.sub(r"[。．.!！?？、,\s…・･]+", "", raw)
    # Keep reactive particles and typical moan lines; drop extreme spam only.
    return len(bare) >= 18


def _is_latin_gibberish(text: str) -> bool:
    raw = str(text or "").strip()
    if not raw:
        return False
    # Short jammed Latin+CJK (HMN-878 Whisper garbage)
    if len(raw) <= 24 and _LATIN_CJK_JAM.search(raw):
        return True
    if not _LATIN_GIBBER.search(raw):
        return False
    # Pure English dialogue is rare in JA AV ASR; mixed kana+latin nonsense is common
    if _KANA_GARBLED.search(raw):
        return True
    letters = sum(1 for ch in raw if ch.isascii() and ch.isalpha())
    cjk = sum(1 for ch in raw if "\u3040" <= ch <= "\u30ff" or "\u4e00" <= ch <= "\u9fff")
    if letters >= 4 and cjk >= 2 and letters >= cjk:
        return True
    return False


def _is_ja_av_asr_junk(text: str) -> bool:
    """Drop logo markers, prompt echoes, and short pure-Han decoder garbage."""
    raw = str(text or "").strip()
    if not raw:
        return True
    bare = re.sub(r"[。．.!！?？、,\s…·・]+", "", raw)
    if bare in _JA_AV_JUNK_EXACT or raw in _JA_AV_JUNK_EXACT:
        return True
    if _PROMPT_LEAK_RE.search(raw):
        return True
    if _SUBTITLE_CREDIT_RE.search(bare):
        return True
    if _HOTWORD_ECHO_RE.match(raw) or _HOTWORD_ECHO_RE.match(bare):
        return True
    # Residual / garbled ギリギリ hotword debris (keep real 「メンエスはギリギリの塩梅」)
    if re.fullmatch(r"[リり]*ギリギリ+の塩梅", bare):
        return True
    if re.fullmatch(r"(?:お客様)?[リりギぎり]{2,24}", bare):
        return True
    if re.search(r"[リり]{1,4}ギリギリ", bare) and "メンエス" not in bare and len(bare) <= 28:
        return True
    has_kana = bool(re.search(r"[\u3040-\u30ff]", bare))
    # Chinese filler loops with no kana (好来好来 / 鼓励鼓励 / 冷冷冷)
    if not has_kana and _ZH_FILLER_LOOP.search(bare) and len(bare) <= 24:
        return True
    # Short pure-Han with a repeated glyph and no JA particles (河河装陀 / 佑佑借佑)
    if (
        len(bare) <= 8
        and _PURE_HAN_REPEAT_JUNK.match(bare)
        and re.search(r"(.)\1", bare)
        and not re.search(r"[はがをにでのともへやも]", bare)
    ):
        return True
    return False


def _compress_hotword_loops(text: str) -> str:
    """Collapse accidental Whisper term repetitions inside otherwise-real cues."""
    s = str(text or "")
    if not s:
        return s
    s = _TERM_LOOP_RE.sub(r"\1", s)
    # Only strip GARBLED salt-plum (leading リ…) — keep real 「ギリギリの塩梅」
    s = re.sub(r"[リり]{1,4}ギリギリ+の塩梅", "", s)
    s = re.sub(r"お客様[リり]*ギリギリ+", "", s)
    s = re.sub(r"お客様[：:][^。\n]{0,48}(?:メンズエステ|マイクロビキニ|メンエス|舞|トミー)[^。\n]{0,24}", "", s)
    return _WS.sub(" ", s).strip(" 、,．.")


def _strip_wet_oral_sfx(text: str) -> str:
    """
    Remove wet/suck/lick onomatopoeia; keep moans and lexical dialogue.

    Whole-cue wet SFX → empty. Mixed cues keep the non-SFX residue
    (e.g. 「ふぅ…ちゅっ…はぁ…」→「ふぅ……はぁ…」).
    """
    s = str(text or "").strip()
    if not s:
        return ""
    if _AV_MISC_SFX_ONLY.match(s) or _WET_ORAL_SFX_ONLY.match(s):
        return ""
    # Protect lexical kiss requests before token strip
    guards: list[tuple[str, str]] = []
    for i, m in enumerate(
        re.finditer(r"(?:ちゅ[ーう]+|チュー+)も?して[よね]?っ?|キスして[よね]?っ?", s)
    ):
        key = f"\uE000{i}\uE001"
        guards.append((key, m.group(0)))
        s = s.replace(m.group(0), key, 1)
    s = _WET_ORAL_SFX_CHUNK.sub("", s)
    for key, orig in guards:
        s = s.replace(key, orig)
    s = _WS.sub(" ", s).strip()
    s = re.sub(r"[、,]{2,}", "、", s)
    s = re.sub(r"[.…]{2,}", "…", s)
    s = re.sub(r"^[、,．.…!！?？\s]+", "", s)
    s = re.sub(r"[、,．.\s]+$", lambda m: "…" if "…" in (m.group(0) or "") else "", s)
    s = s.strip(" 、,")
    return s.strip()


def clean_cue_text(text: str, *, ja_av: bool = True) -> str:
    """Strip SFX/SDH markers from one cue line; optionally JA-AV sanitize."""
    s = str(text or "")
    if not s:
        return ""
    # Latin Whisper artifacts (▁, spaced apostrophes, digit splits, camel glue)
    if "\u2581" in s:
        s = s.replace("\u2581", " ")
    _apos_suffixes = {"m", "s", "re", "ve", "ll", "d", "t", "am", "em"}

    def _apos(m: re.Match[str]) -> str:
        left, right = m.group(1), m.group(2)
        if right.lower() in _apos_suffixes or len(right) <= 2:
            return f"{left}'{right}"
        return f"{left} {right}"

    for _ in range(3):
        nxt = re.sub(r"\b([A-Za-z]+)\s+'\s*([A-Za-z]+)\b", _apos, s)
        if nxt == s:
            break
        s = nxt
    for _ in range(4):
        nxt = re.sub(r"(?<!\d)(\d)\s+(\d)(?!\d)", r"\1\2", s)
        if nxt == s:
            break
        s = nxt
    s = re.sub(r"([a-z])([A-Z])", r"\1 \2", s)
    s = re.sub(r"\s+([,.!?;:])", r"\1", s)
    s = _SFX_BRACKET.sub("", s)
    s = _TORTOISE.sub("", s)
    s = _MUSIC_TOKEN.sub("", s)
    s = _SHORT_PAREN.sub("", s)
    s = _WS.sub(" ", s).strip()
    if not s or _WHOLE_SFX.match(s) or _SYMBOL_ONLY.match(s):
        return ""
    if ja_av:
        s = _strip_wet_oral_sfx(s)
        if not s or _SYMBOL_ONLY.match(s):
            return ""
        if _is_latin_gibberish(s) or _is_nvv_only(s) or _is_ja_av_asr_junk(s):
            return ""
        if _STUTTER_COMMA_ONLY.match(s):
            first = re.match(r"^([あぁアァうぅウゥんンー〜～っッ]{1,2})", s)
            s = f"{first.group(1)}、{first.group(1)}" if first else "あ、あ"
        else:
            s = _compress_stutter_phrases(s)
        s = _compress_elongated(s)
        s = _compress_hotword_loops(s)
        s = _apply_ja_asr_domain_fixes(s)
        s = _strip_wet_oral_sfx(s)
        s = _WS.sub(" ", s).strip()
        if not s or _SYMBOL_ONLY.match(s) or _is_nvv_only(s) or _is_ja_av_asr_junk(s):
            return ""
    return s


def clean_cues(
    cues: list[dict[str, Any]] | None,
    *,
    ja_av: bool = True,
) -> list[dict[str, Any]]:
    """
    Clean cue texts in place-copy; drop cues that become empty.

    Preserves start/end and other fields.
    """
    if not cues:
        return []
    out: list[dict[str, Any]] = []
    for cue in cues:
        if not isinstance(cue, dict):
            continue
        cleaned = dict(cue)
        cleaned["text"] = clean_cue_text(str(cue.get("text") or ""), ja_av=ja_av)
        if cleaned["text"]:
            out.append(cleaned)
    return out
